{
	"name": "@madisonbullard/opencode-private-share",
	"version": "0.2.1",
	"description": "OpenCode plugin that handles sharing to private AWS infra.",
	"author": "madisonbullard",
	"license": "MIT",
	"publishConfig": {
		"access": "public"
	},
	"repository": {
		"type": "git",
		"url": "https://github.com/madisonbullard/opencode-tools.git",
		"directory": "packages/plugins/private-share"
	},
	"type": "module",
	"main": "dist/index.js",
	"types": "dist/index.d.ts",
	"files": [
		"dist"
	],
	"scripts": {
		"build": "tsc",
		"prepublishOnly": "bun run build",
		"typecheck": "tsc --noEmit"
	},
	"keywords": [
		"opencode",
		"opencode-plugin",
		"share",
		"session"
	],
	"devDependencies": {
		"@types/node": "22.15.1",
		"typescript": "5.9.3"
	},
	"dependencies": {
		"@madisonbullard/opencode-scripts": "^0.2.1",
		"@opencode-ai/plugin": "1.0.207",
		"@opencode-ai/sdk": "1.0.207",
		"zod": "4.2.1"
	}
}
